-- Синтетический набор на 08.10.2026; реальные токены и платежи не используются.
BEGIN;
SET search_path TO progressly, public;
SET LOCAL TIME ZONE 'UTC';





SELECT e.id, f.id, e.tracker_id, f.kind, x.val
FROM (VALUES ('2026-10-05'::date,'Сон, ч',7.0), ('2026-10-05','Настроение',7),
             ('2026-10-06','Сон, ч',8), ('2026-10-06','Настроение',8),
             ('2026-10-07','Сон, ч',7.5)) x(day,name,val)
JOIN entry e ON e.entry_date = x.day AND e.tracker_id = '10000000-0000-4000-8000-000000000001'
JOIN tracker_field f ON f.tracker_id = e.tracker_id AND f.name = x.name;


  '40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001',
  '20000000-0000-4000-8000-000000000001','NUMBER','Спать в среднем не меньше 7,5 ч',7.5,
  '2026-10-05','2026-10-08','ACHIEVED');

  'Средняя длительность сна за три дня — 7,5 часа.',
  ARRAY['Цель по средней длительности сна достигнута.'],
  ARRAY['Продолжайте отмечать время отбоя.'],'2026-10-08 08:00',NULL);
COMMIT;
